{"status":"ok"}<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #202b3c; background: #f4f7fb; }
    * { box-sizing: border-box; }
    body { margin: 0; min-height: 100vh; }
    header { background: #17365d; color: white; padding: 1rem max(1.25rem, calc((100% - 900px) / 2)); }
    header strong { font-size: 1.15rem; }
    main { width: min(900px, calc(100% - 2rem)); margin: 2.5rem auto; }
    h1 { margin: 0 0 1.5rem; font-size: 2rem; }
    .card { background: white; border: 1px solid #dce3ed; border-radius: 10px; padding: 1.5rem; box-shadow: 0 2px 8px #1e3a5f0a; }
    form { display: flex; align-items: end; gap: .75rem; flex-wrap: wrap; }
    label { display: grid; gap: .4rem; font-weight: 600; flex: 1 1 250px; }
    input { font: inherit; padding: .65rem .75rem; border: 1px solid #9aa9bb; border-radius: 5px; }
    button { font: inherit; font-weight: 600; border: 0; border-radius: 5px; padding: .7rem 1rem; color: white; background: #245a9b; cursor: pointer; }
    button:hover { background: #173f70; }
    button:focus-visible, input:focus-visible { outline: 3px solid #78aef0; outline-offset: 2px; }
    [role=alert] { color: #a32222; margin: .8rem 0 0; }
    .project-list { list-style: none; padding: 0; margin: 1.25rem 0 0; }
    .project-row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1rem 0; border-top: 1px solid #e1e7ef; }
    .project-name { font-weight: 600; overflow-wrap: anywhere; }
    .empty { color: #627187; margin: 1.25rem 0 0; }
    .back { margin-bottom: 1rem; background: #52667e; }
  </style>
</head>
<body>
  <header><strong>Workboard</strong></header>
  <main id="app" aria-live="polite"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeText = value => value;

    async function loadProjects() {
      const response = await fetch('/api/projects');
      return response.json();
    }

    async function showList() {
      app.innerHTML = `
        <h1>Workboard</h1>
        <section class="card" aria-label="Projects">
          <form id="create-form">
            <label for="project-name">Project name</label>
            <input id="project-name" name="name" type="text" autocomplete="off">
            <button type="submit">Create project</button>
          </form>
          <p id="error" role="alert" hidden></p>
          <ul class="project-list" id="projects"></ul>
        </section>`;
      const form = app.querySelector('#create-form');
      const input = app.querySelector('#project-name');
      const list = app.querySelector('#projects');
      const error = app.querySelector('#error');
      const render = async () => {
        const projects = await loadProjects();
        list.replaceChildren();
        if (!projects.length) {
          const empty = document.createElement('li');
          empty.className = 'empty';
          empty.textContent = 'No projects yet.';
          list.append(empty);
        }
        for (const project of projects) {
          const row = document.createElement('li');
          row.className = 'project-row';
          row.dataset.testid = 'project-row';
          const name = document.createElement('span');
          name.className = 'project-name';
          name.textContent = escapeText(project.name);
          const open = document.createElement('button');
          open.type = 'button';
          open.textContent = 'Open project';
          open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
          row.append(name, open);
          list.append(row);
        }
      };
      form.addEventListener('submit', async event => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          error.textContent = 'Project name is required';
          error.hidden = false;
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
        });
        if (!response.ok) return;
        input.value = '';
        error.hidden = true;
        await render();
      });
      await render();
    }

    async function showProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) { history.replaceState({}, '', '/'); return showList(); }
      const project = await response.json();
      app.innerHTML = '<button class="back" type="button">Projects</button><h1></h1>';
      app.querySelector('.back').addEventListener('click', () => { location.href = '/'; });
      app.querySelector('h1').textContent = project.name;
    }

    const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
    if (match) showProject(match[1]); else showList();
  </script>
</body>
</html>
